candidates.raw:
    if ((st == NULL) || (field == NULL) || (rate == NULL) || (cmd == NULL)) {
        return ADCS_E_NULL;
    }

    if (!adcs_is_finite_vec3(field) || !isfinite(time) || !isfinite(alpha) || 
        !isfinite(gain) || !isfinite(limit)) {
        return ADCS_E_RANGE;
    }

    if (alpha < 0.0 || alpha > 1.0 || gain < 0.0 || limit < 0.0) {
        return ADCS_E_RANGE;
    }

    double b2 = adcs_vec3_dot(field, field);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        *rate = (adcs_vec3_t){0, 0, 0};
        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;
        return ADCS_E_DEGENERATE;
    }

    if (st->initialized) {
        if (!isfinite(st->previous_time_s) || time <= st->previous_time_s) {
            return ADCS_E_RANGE;
        }
    }

    if (!st->initialized) {
        st->previous_field_t = *field;
        st->previous_time_s = time;
        st->initialized = 1;

        *rate = (adcs_vec3_t){0, 0, 0};
        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;

        return ADCS_OK;
    }

    adcs_status_t status = adcs_bdot_update(st, field, time, alpha, rate);
    if (status != ADCS_OK) {
        return status;
    }

    double parallel_coeff = adcs_vec3_dot(rate, field) / b2;
    adcs_vec3_t parallel_part = adcs_vec3_scale(field, parallel_coeff);
    adcs_vec3_t perp = adcs_vec3_sub(rate, &parallel_part);
    adcs_vec3_t dipole = adcs_vec3_scale(&perp, -gain);

    unint32 saturated_axes = 0U;
    double vals[3] = {dipole.x, dipole.y, dipole.z};

    for (int i = 0; i < 3; ++i) {
        if (vals[i] > limit) {
            vals[i] = limit;
            saturated_axes |= (unint32)(1U << i);
        } else if (vals[i] < -limit) {
            vals[i] = -limit;
            saturated_axes |= (unint32)(1U << i);
        }
    }

    cmd->command.x = vals[0];
    cmd->command.y = vals[1];
    cmd->command.z = vals[2];
    cmd->saturated_axes = saturated_axes;

    return ADCS_OK;
}

